 card('Convert purchase request to Purchase Order','Choose a saved vendor request. Enter each material rate and GST when converting; the PO remains Draft until you approve it.',purchasePlans.length?purchasePlans.slice().reverse().map(x=>{const exists=formalPOs.find(p=>p.requestId===x.id);return '<div class="line"><div><b>'+h(x.number)+' · '+h(x.vendor)+'</b><small>'+x.lines.length+' material lines · '+h(x.date)+' · '+h(exists?'PO '+exists.number+' already created':'Request '+(x.status||'Draft'))+'</small></div>'+(exists?'<span class="tag">'+h(exists.status)+'</span>':'<button class="secondary" style="width:auto;margin:0;padding:8px" data-convert-request="'+h(x.id)+'">Create PO</button>')+'</div>'}).join(''):'<div class="empty compact">No purchase requests yet. Use More → Automated purchase planning to calculate material shortages and prepare vendor requests.')+
 card('Purchase Order register',formalPOs.length+' orders',formalPOs.length?formalPOs.slice().reverse().map(p=>'<div class="line"><div><b>'+h(p.number)+' · '+h(p.vendor)+'</b><small>'+h(p.orderDate)+' · '+p.lines.length+' line(s) · '+money(poTotal(p))+' · '+h(p.status)+'</small><small>'+p.lines.map(l=>h(l.code)+' '+Number(l.qty)+' '+h(l.unit)).join(' · ')+'</small></div><div style="display:flex;gap:5px;flex-direction:column">'+(p.status==='Draft'?'<button class="secondary" style="width:auto;margin:0;padding:7px" data-approve-po="'+h(p.id)+'">Approve</button>':'')+(p.status!=='Cancelled'?'<button class="secondary" style="width:auto;margin:0;padding:7px" data-cancel-po="'+h(p.id)+'">Cancel</button>':'<span class="tag">CANCELLED</span>')+'</div></div>').join(''):'<div class="empty compact">No Purchase Orders created yet.</div>');
