function postAcceptedStock(po,line,grn,qty,qcId){
 if(qty<=0)return;
 if(line.itemType==='Fabric'){
  if(!grn.roll)throw new Error('Fabric GRN needs a unique roll number before QC stock posting.');
  const existing=fabrics.find(x=>x.grnId===grn.id);
  if(existing){if(norm(existing.roll)!==norm(grn.roll))throw new Error('The roll number on this GRN was changed after its first QC posting.');existing.meters=Number(existing.meters||0)+qty;existing.lastAcceptedAt=new Date().toISOString();}
  else{if(fabrics.some(x=>norm(x.roll)===norm(grn.roll)))throw new Error('Fabric roll number '+grn.roll+' already exists. Change the GRN roll number before posting.');fabrics.push({id:'FAB-GRN-'+qcId,type:'Purchased',code:line.code,design:grn.design||'',roll:grn.roll,colour:line.colour||'',width:grn.width||'',gsm:grn.gsm||'',meters:qty,supplier:po.vendor,lot:grn.supplierLot||grn.supplierChallan||grn.number,grnId:grn.id,poId:po.id,acceptedAt:new Date().toISOString()});}
  fs(FK.fabric,fabrics);
 }else if(line.itemType==='Accessory'){
  if(!accessories.some(x=>x.id===line.itemId))throw new Error('Linked accessory master was not found. No stock was posted.');
  trimlogs.push({id:'TRM-GRN-'+qcId,itemId:line.itemId,kind:'IN',qty,date:grn.date,orderId:'PURCHASE',reference:grn.number,category:'Purchase GRN',supplier:po.vendor,poId:po.id,grnId:grn.id,notes:'QC accepted stock'});
  fs(FK.trimlog,trimlogs);
 }else throw new Error('Unsupported material type. Stock not posted.');
}
