window.restoreBusinessBackup=function(file){
 if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const b=JSON.parse(String(reader.result||''));if(!b||b.format!=='prasad-business-analyst-backup'||b.version!==1||!b.data||typeof b.data!=='object')throw new Error('Unsupported backup file.');const allowed=['pa_manufacturing_v1','pa_drafts','pa_orders','pa_tax_invoices','pa_invoice_profile','pa_barcode_catalog_v1',K.moves,K.holds,K.labels,FK.fabric,FK.cut,FK.trim,FK.trimlog,BK,SUPK,PK,POK,GRNK,PAYK],entries=Object.entries(b.data);if(!entries.length||entries.some(([k,v])=>(!allowed.includes(k)&&!/^pa_invoice_seq_\\d{2}-\\d{2}$/.test(k))||typeof v!=='string'))throw new Error('Backup data is invalid.');for(const k of allowed){if(b.data[k]!==undefined){const parsed=JSON.parse(b.data[k]);if(!Array.isArray(parsed)&&!(k==='pa_manufacturing_v1'&&parsed&&typeof parsed==='object'))throw new Error('Invalid '+k+' data.');}}if(!confirm('Restore this backup? Current records will be replaced.'))return;window.backupKeys().forEach(k=>localStorage.removeItem(k));entries.forEach(([k,v])=>localStorage.setItem(k,v));alert('Backup restored. Reloading.');location.reload();}catch(e){alert('Restore failed: '+e.message)}};reader.readAsText(file);
};


